import{_ as a,C as s,o as r,c as n,a0 as o,b as d,w as e,a as l,E as c,a1 as h}from"./chunks/framework.D7EjqxMK.js";const O=JSON.parse('{"title":"01 · micro-ROS 与嵌入式","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/05_前沿趋势/01_microROS2与嵌入式.md","filePath":"08-ros/05_前沿趋势/01_microROS2与嵌入式.md"}'),g={name:"08-ros/05_前沿趋势/01_microROS2与嵌入式.md"};function S(p,t,u,m,R,C){const i=s("Mermaid");return r(),n("div",null,[t[1]||(t[1]=o('<h1 id="_01-·-micro-ros-与嵌入式" tabindex="-1">01 · micro-ROS 与嵌入式 <a class="header-anchor" href="#_01-·-micro-ros-与嵌入式" aria-label="Permalink to &quot;01 · micro-ROS 与嵌入式&quot;">​</a></h1><blockquote><p><strong>位置</strong>：08-ROS / 05_前沿趋势 <strong>难度</strong>：⭐（入门级，理解定位与架构即可） <strong>前置知识</strong>：<a href="./../01_基础概念/">模块一：ROS 2 节点/话题/服务基础</a>、<a href="./../02_核心模块/">模块二：DDS 通信模型与 RMW</a><strong>最后更新</strong>：2026-08-25</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>micro-ROS 是 ROS 2 官方生态中面向 <strong>资源极度受限微控制器（MCU）</strong> 的延伸子项目，目标是把 ROS 2 的编程模型（节点、话题、服务、动作）带到运行 <strong>RTOS 或裸机</strong> 的嵌入式芯片上：ARM Cortex-M 系列、RISC-V、DSP，以及带 Wi-Fi 的 SoC（如 ESP32）。它的核心思路不是&quot;把整个 ROS 2 塞进 MCU&quot;，而是做一个<strong>轻量客户端</strong>，通过网络（串口/UART、UDP、TCP、6LoWPAN）把话题和服务代理到一个跑在 PC 或 MPU 上的 <strong>micro-ROS Agent</strong>，由 Agent 替 MCU 完成与标准 DDS 网络的对接。</p><p>一句话定位：<strong>micro-ROS 让一颗几十 KB RAM 的单片机，以&quot;一等公民&quot;身份加入 ROS 2 的 DDS 数据总线</strong>，从而打通&quot;传感器 MCU → 边缘计算 → 云端/整机&quot;的完整链路。</p><hr><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><h3 id="_2-1-micro-ros-的定位-ros-2-的-瘦客户端" tabindex="-1">2.1 micro-ROS 的定位：ROS 2 的&quot;瘦客户端&quot; <a class="header-anchor" href="#_2-1-micro-ros-的定位-ros-2-的-瘦客户端" aria-label="Permalink to &quot;2.1 micro-ROS 的定位：ROS 2 的&quot;瘦客户端&quot;&quot;">​</a></h3><p>micro-ROS 不是新的机器人框架，而是 ROS 2 的一个<strong>集成层</strong>。它复用了 ROS 2 的标准接口定义（ROS 2 客户端库 API、.msg/.srv/.action 类型、话题/服务/动作语义），但在实现上做了大幅裁剪：</p><table tabindex="0"><thead><tr><th>维度</th><th>标准 ROS 2 节点（rclcpp/rclpy）</th><th>micro-ROS 节点</th></tr></thead><tbody><tr><td>目标硬件</td><td>PC / MPU（Ubuntu、Windows、macOS）</td><td>MCU（Cortex-M、RISC-V、ESP32）</td></tr><tr><td>操作系统</td><td>Linux / Windows / macOS</td><td>RTOS（FreeRTOS、Zephyr、NuttX）或裸机</td></tr><tr><td>中间件</td><td>完整 DDS（Fast DDS、Cyclone DDS 等）</td><td>Micro XRCE-DDS（见 2.2）</td></tr><tr><td>内存占用</td><td>数十 MB 级</td><td>数十 KB 级（RAM 可低至 10 KB 量级）</td></tr></tbody></table><h3 id="_2-2-micro-xrce-dds-给-dds-做的-极瘦-协议" tabindex="-1">2.2 Micro XRCE-DDS：给 DDS 做的&quot;极瘦&quot;协议 <a class="header-anchor" href="#_2-2-micro-xrce-dds-给-dds-做的-极瘦-协议" aria-label="Permalink to &quot;2.2 Micro XRCE-DDS：给 DDS 做的&quot;极瘦&quot;协议&quot;">​</a></h3><p>DDS 的完整实现（含 RTPS 线协议、发现机制、QoS 协商）对 MCU 太重。micro-ROS 底层采用 <strong>Micro XRCE-DDS</strong>（DDS for eXtremely Resource Constrained Environments），由 eProsima 维护，是一个<strong>客户端-代理（Client–Agent）</strong> 协议：</p><ul><li><strong>XRCE Client</strong>：运行在 MCU 上，只实现一套精简的请求/响应语义（创建实体、发布/订阅、读写数据）；</li><li><strong>XRCE Agent</strong>：运行在资源充足的主机上，持有真正的 DDS 实体，代表 Client 与完整 DDS 域通信。</li></ul><p>这套设计把重量级的 DDS 发现、序列化、传输细节全部推给 Agent，MCU 只保留最必要的状态机。</p><h3 id="_2-3-client-agent-的双进程架构" tabindex="-1">2.3 Client + Agent 的双进程架构 <a class="header-anchor" href="#_2-3-client-agent-的双进程架构" aria-label="Permalink to &quot;2.3 Client + Agent 的双进程架构&quot;">​</a></h3><p>micro-ROS 的运行时由两部分构成，它们之间通过一条可插拔的<strong>传输层</strong>（transport）通信：</p><ul><li><strong>micro-ROS Client（节点端）</strong>：MCU 上由 <code>rclc</code>（micro-ROS 客户端库，基于 rcl）驱动的节点、发布器、订阅器、服务、执行器；</li><li><strong>micro-ROS Agent（代理端）</strong>：通常是一个独立进程 <code>micro-ROS-Agent</code>，通过命令行指定串口或 UDP 端口接入，并把 Client 的话题桥接到本机的 DDS 域。</li></ul>',18)),(r(),d(h,null,{default:e(()=>[c(i,{id:"mermaid-128",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20MCU%5B%22MCU%EF%BC%88Cortex-M%20%2F%20RISC-V%20%2F%20ESP32%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%2F%E6%89%A7%E8%A1%8C%E5%99%A8%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22micro-ROS%20Client%3Cbr%2F%3E(rclc%20%2B%20%E8%8A%82%E7%82%B9%2F%E5%8F%91%E5%B8%83%E5%99%A8%2F%E8%AE%A2%E9%98%85%E5%99%A8)%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22XRCE%20Client%22%5D%0A%20%20%20%20%20%20%20%20A%20--%3E%20B%20--%3E%20C%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Host%5B%22%E4%B8%BB%E6%9C%BA%EF%BC%88PC%20%2F%20%E8%BE%B9%E7%BC%98%20MPU%EF%BC%8C%E5%A6%82%20Jetson%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22XRCE%20Agent%3Cbr%2F%3E(micro-ROS-Agent)%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22Fast%20DDS%20%2F%20Cyclone%20DDS%3Cbr%2F%3E(%E6%A0%87%E5%87%86%20DDS%20%E5%9F%9F)%22%5D%0A%20%20%20%20%20%20%20%20F%5B%22%E6%A0%87%E5%87%86%20ROS%202%20%E8%8A%82%E7%82%B9%3Cbr%2F%3E(rclcpp%20%2F%20rclpy)%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%7C%22UART%20%2F%20UDP%20%2F%20TCP%20%2F%206LoWPAN%22%7C%20D%0A%20%20%20%20%20%20%20%20D%20--%3E%20E%0A%20%20%20%20%20%20%20%20F%20--%3E%20E%0A%20%20%20%20end%0A%0A%20%20%20%20E%20-.-%3E%7C%22%E5%90%8C%E4%B8%80%20DDS%20%E7%BD%91%E7%BB%9C%22%7C%20G%5B%22%E5%85%B6%E4%BD%99%20ROS%202%20%E8%8A%82%E7%82%B9%20%2F%20%E5%8F%AF%E8%A7%86%E5%8C%96%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o(`<h3 id="_2-4-与标准-ros-2-节点的互通" tabindex="-1">2.4 与标准 ROS 2 节点的互通 <a class="header-anchor" href="#_2-4-与标准-ros-2-节点的互通" aria-label="Permalink to &quot;2.4 与标准 ROS 2 节点的互通&quot;">​</a></h3><p>micro-ROS 的<strong>关键价值</strong>在于&quot;透明互通&quot;：Agent 把 Client 侧的话题直接映射到标准 DDS 域后，任何标准 ROS 2 节点（rclcpp/rclpy）都能像订阅普通话题一样订阅 MCU 发出的数据，反之亦然。因此 MCU 侧代码里的 <code>rclc_publisher_publish()</code>，在主机的 <code>ros2 topic echo /imu</code> 里就能直接看到——开发者无需关心底层的 XRCE 协议细节。</p><hr><h2 id="_3-技术原理-现状分析" tabindex="-1">3. 技术原理 / 现状分析 <a class="header-anchor" href="#_3-技术原理-现状分析" aria-label="Permalink to &quot;3. 技术原理 / 现状分析&quot;">​</a></h2><h3 id="_3-1-官方支持平台-已核实" tabindex="-1">3.1 官方支持平台（已核实） <a class="header-anchor" href="#_3-1-官方支持平台-已核实" aria-label="Permalink to &quot;3.1 官方支持平台（已核实）&quot;">​</a></h3><p>micro-ROS 官方文档与硬件支持列表明确指出其跨 RTOS、跨芯片的定位（来源见第 7 节）：</p><ul><li><strong>RTOS 支持</strong>：FreeRTOS、Zephyr、NuttX（以及基于它们的分支）；</li><li><strong>芯片/开发板</strong>：官方硬件支持页（micro.vulcanexus.org 的 Supported Hardware 页）列出 Olimex STM32-E407、ESP32 系列、Zephyr 支持的大量板卡（Nordic nRF、ST Nucleo 等）；</li><li><strong>传输层</strong>：串口（UART）、UDP、TCP、自定义传输（如 6LoWPAN、CAN、SPI 等可扩展）；</li><li><strong>与 RTOS 无关性</strong>：micro-ROS 官方明确其&quot;RTOS 无关 / 硬件无关&quot;的设计目标。</li></ul><blockquote><p>⚠️ 提示：硬件列表会随版本演进，具体板卡请以 micro.ros.org 与 micro.vulcanexus.org 的&quot;Supported Hardware&quot;页实时内容为准，本文不逐板卡罗列。</p></blockquote><h3 id="_3-2-功能覆盖-不是-全部-ros-2" tabindex="-1">3.2 功能覆盖：不是&quot;全部 ROS 2&quot; <a class="header-anchor" href="#_3-2-功能覆盖-不是-全部-ros-2" aria-label="Permalink to &quot;3.2 功能覆盖：不是&quot;全部 ROS 2&quot;&quot;">​</a></h3><p>micro-ROS 官方提供了一张 <strong>ROS 2 特性对照表</strong>（micro.ros.org 的 &quot;ROS 2 feature comparison&quot; 页），明确标注哪些 ROS 2 特性已支持、部分支持或不支持。要点：</p><ul><li><strong>支持</strong>：节点、话题发布/订阅、服务客户端/服务端、动作（有限支持）、QoS 基础能力、<code>.msg/.srv</code> 类型；</li><li><strong>受限/不支持</strong>：完整的 DDS 发现与多域能力、部分高级 QoS、部分 rclcpp 高级特性；</li><li><strong>执行模型</strong>：micro-ROS 提供单线程执行器（executor），由用户显式调用 <code>rclc_executor_spin_some()</code>，天然契合 RTOS 的任务调度模型。</li></ul><h3 id="_3-3-典型落地场景" tabindex="-1">3.3 典型落地场景 <a class="header-anchor" href="#_3-3-典型落地场景" aria-label="Permalink to &quot;3.3 典型落地场景&quot;">​</a></h3><ol><li><strong>传感器节点</strong>：IMU、编码器、温湿度、距离传感器等直接挂在 MCU 上，以话题对外广播（例如 <code>/imu</code>、<code>/odom</code>）；</li><li><strong>低成本控制器/执行器节点</strong>：电机驱动、舵机、继电器控制，通过服务或话题接收指令；</li><li><strong>机群/外设解耦</strong>：把大量低速率外设从主控下放到多个 MCU，主控只跑核心算法。</li></ol><hr><h2 id="_4-实践指南-当前可落地路径" tabindex="-1">4. 实践指南（当前可落地路径） <a class="header-anchor" href="#_4-实践指南-当前可落地路径" aria-label="Permalink to &quot;4. 实践指南（当前可落地路径）&quot;">​</a></h2><h3 id="_4-1-最小闭环-让-mcu-话题出现在主机-ros-2-里" tabindex="-1">4.1 最小闭环：让 MCU 话题出现在主机 ROS 2 里 <a class="header-anchor" href="#_4-1-最小闭环-让-mcu-话题出现在主机-ros-2-里" aria-label="Permalink to &quot;4.1 最小闭环：让 MCU 话题出现在主机 ROS 2 里&quot;">​</a></h3><p><strong>Step 1 — 准备主机侧 Agent</strong>（Ubuntu 上，已装 ROS 2）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通过官方安装脚本或包管理器安装 micro_ros_agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> micro-ros-agent</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 官方提供 snap（示例，以官方文档为准）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以串口方式启动 Agent（/dev/ttyUSB0 为例）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">micro-ros-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serial</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 115200</span></span></code></pre></div><blockquote><p>示例命令，需根据实际框架/发行版调整。</p></blockquote><p><strong>Step 2 — 构建 MCU 固件</strong>：使用 <code>micro_ros_setup</code> 或直接在工程里引入 <code>rclc</code> + <code>Micro XRCE-DDS</code>，配置与 Agent 相同的传输（串口波特率、UDP 端口等）。</p><p><strong>Step 3 — 验证互通</strong>：MCU 上电后，在主机执行 <code>ros2 topic list</code> 应能看到 MCU 发布的话题；<code>ros2 topic echo</code> 可直接读取数据。</p><h3 id="_4-2-选型建议" tabindex="-1">4.2 选型建议 <a class="header-anchor" href="#_4-2-选型建议" aria-label="Permalink to &quot;4.2 选型建议&quot;">​</a></h3><ul><li><strong>只想快速验证</strong>：ESP32（有成熟社区样例与 Arduino 库 micro_ros_arduino）；</li><li><strong>要量产/低功耗</strong>：Cortex-M + FreeRTOS/Zephyr，配合自研传输；</li><li><strong>已有 RTOS 工程</strong>：优先评估 Zephyr（官方支持度高），其次 FreeRTOS。</li></ul><hr><h2 id="_5-方案对比" tabindex="-1">5. 方案对比 <a class="header-anchor" href="#_5-方案对比" aria-label="Permalink to &quot;5. 方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适用目标</th><th>资源需求</th><th>与标准 ROS 2 互通</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>micro-ROS</strong></td><td>MCU / RTOS</td><td>极低（几十 KB RAM）</td><td>通过 Agent 透明互通</td><td>传感器/执行器/低成本节点</td></tr><tr><td><strong>标准 ROS 2（rclcpp/rclpy）</strong></td><td>MPU / Linux</td><td>高（数十 MB+）</td><td>原生</td><td>定位、建图、规划、视觉</td></tr><tr><td><strong>裸 UART/自定义协议 + 网关</strong></td><td>极简外设</td><td>最低</td><td>需自写桥接</td><td>非 ROS 生态的既有外设</td></tr><tr><td><strong>ROS 1（roscpp）在嵌入式</strong></td><td>老系统兼容</td><td>中</td><td>需 ros1_bridge</td><td>存量 ROS 1 设备</td></tr></tbody></table><p><strong>绝对不适用场景</strong>：需要高吞吐、大数据量（如原始点云/图像流）的<strong>本地实时处理</strong>。micro-ROS 的目标是低速率的控制与传感器数据，把高清视频流走 XRCE 到 MCU 既无意义也会击穿其带宽与内存设计边界；这类负载应直接由 MPU 上的标准 ROS 2 节点承担。</p><hr><h2 id="_6-工具链" tabindex="-1">6. 工具链 <a class="header-anchor" href="#_6-工具链" aria-label="Permalink to &quot;6. 工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具/组件</th><th>作用</th><th>来源</th></tr></thead><tbody><tr><td><code>micro-ROS-Agent</code></td><td>主机侧代理进程</td><td>micro-ROS 官方仓库</td></tr><tr><td><code>micro_ros_setup</code></td><td>工程/固件脚手架生成</td><td>micro-ROS 官方仓库</td></tr><tr><td><code>rclc</code></td><td>MCU 侧客户端库（基于 rcl）</td><td>micro-ROS 官方仓库</td></tr><tr><td>Micro XRCE-DDS</td><td>底层 Client–Agent 协议</td><td>eProsima</td></tr><tr><td><code>micro_ros_arduino</code></td><td>Arduino 生态封装</td><td>micro-ROS 官方仓库</td></tr><tr><td>Vulcanexus micro</td><td>eProsima 打包的 micro-ROS 发行版与文档</td><td>micro.vulcanexus.org</td></tr><tr><td>Docker 镜像</td><td>官方编译/调试环境</td><td>micro-ROS/docker</td></tr></tbody></table><hr><h2 id="_7-参考资料-均经核实" tabindex="-1">7. 参考资料（均经核实） <a class="header-anchor" href="#_7-参考资料-均经核实" aria-label="Permalink to &quot;7. 参考资料（均经核实）&quot;">​</a></h2><ul><li>micro-ROS 官网：<a href="https://micro.ros.org/" target="_blank" rel="noreferrer">https://micro.ros.org/</a></li><li>micro-ROS 源码组织：<a href="https://github.com/micro-ros" target="_blank" rel="noreferrer">https://github.com/micro-ros</a></li><li>官方硬件支持列表：<a href="https://micro.vulcanexus.org/docs/overview/hardware/" target="_blank" rel="noreferrer">https://micro.vulcanexus.org/docs/overview/hardware/</a></li><li>Micro XRCE-DDS 概念文档：<a href="https://micro.vulcanexus.org/docs/concepts/middleware/Micro_XRCE-DDS/" target="_blank" rel="noreferrer">https://micro.vulcanexus.org/docs/concepts/middleware/Micro_XRCE-DDS/</a></li><li>eProsima Micro XRCE-DDS 产品页：<a href="https://www.eprosima.com/middleware/add-ons/micro-xrce-dds" target="_blank" rel="noreferrer">https://www.eprosima.com/middleware/add-ons/micro-xrce-dds</a></li><li>ROS 2 特性对照表：<a href="https://micro.ros.org/docs/overview/ROS_2_feature_comparison/" target="_blank" rel="noreferrer">https://micro.ros.org/docs/overview/ROS_2_feature_comparison/</a></li><li>micro-ROS Docker：<a href="https://github.com/micro-ROS/docker" target="_blank" rel="noreferrer">https://github.com/micro-ROS/docker</a></li><li>micro_ros_arduino（系统要求）：<a href="https://github.com/micro-ROS/micro_ros_arduino" target="_blank" rel="noreferrer">https://github.com/micro-ROS/micro_ros_arduino</a></li></ul><hr><h2 id="_8-学习路径" tabindex="-1">8. 学习路径 <a class="header-anchor" href="#_8-学习路径" aria-label="Permalink to &quot;8. 学习路径&quot;">​</a></h2><ol><li><strong>打底</strong>：先理解 ROS 2 话题/服务的语义（模块一），再理解 DDS/RMW 的角色（模块二）；</li><li><strong>跑通样例</strong>：用 ESP32 + 官方 Arduino 样例，让 <code>/imu</code> 出现在主机 <code>ros2 topic list</code>；</li><li><strong>看懂协议</strong>：通读 Micro XRCE-DDS 概念文档，弄清 Client/Agent 的实体生命周期；</li><li><strong>进阶</strong>：把 micro-ROS 接入自研 Cortex-M 工程（FreeRTOS/Zephyr），自定义传输层；</li><li><strong>纵向延伸</strong>：结合 <a href="./04_ROS2跨平台与Web节点.html">模块五 04 · 跨平台与 Web 节点</a> 理解边缘侧（Jetson）如何承接 MCU 与云端之间。</li></ol><hr><h2 id="_9-核心面试三问" tabindex="-1">9. 核心面试三问 <a class="header-anchor" href="#_9-核心面试三问" aria-label="Permalink to &quot;9. 核心面试三问&quot;">​</a></h2><p><strong>Q1：micro-ROS 为什么能跑在几十 KB RAM 的 MCU 上，却还能和标准 ROS 2 节点互通？</strong> 答：它把完整 DDS 的重量级工作（发现、序列化、QoS 协商、传输）委托给主机侧的 <strong>micro-ROS Agent</strong>，MCU 侧只跑一套极瘦的 <strong>XRCE Client</strong>（Micro XRCE-DDS 协议），通过串口/UDP 等轻量传输与 Agent 通信；Agent 把 MCU 的实体映射进标准 DDS 域，因此对 rclcpp/rclpy 节点&quot;透明&quot;。</p><p><strong>Q2：micro-ROS 和&quot;标准 ROS 2 装进嵌入式 Linux（如 Raspberry Pi）&quot;有什么本质区别？</strong> 答：二者目标不同——Pi 属于 MPU，跑完整 Linux + 完整 DDS，是&quot;标准 ROS 2&quot;；micro-ROS 面向 <strong>MCU/RTOS</strong>，靠 Client–Agent 代理接入。判断边界看资源与 OS：能跑 Linux 就用标准 ROS 2，只有 MCU/RTOS 才需要 micro-ROS。</p><p><strong>Q3：micro-ROS 最大的局限是什么？在什么场景下你会放弃它？</strong> 答：带宽与功能子集。它适合低速率的控制/传感器数据，不适合大吞吐流（原始点云/图像）；且部分高级 QoS、多域 DDS 能力受限。遇到高带宽本地处理、强实时确定性控制（需硬实时）或需要完整 DDS 语义的场景，我会改用 MPU + 标准 ROS 2（必要时配合实时内核，见模块三实时性内容）。</p>`,41))])}const D=a(g,[["render",S]]);export{O as __pageData,D as default};
